INSERT INTO `dosages` VALUES (1,24,'Inhaled salbutamol: maximum 1600 micrograms over 24 hours in divided doses not to exceed 600 micrograms over 8 hours starting from any dose'),(2,27,'Inhaled formoterol: maximum delivered dose of 54 micrograms over 24 hours'),(3,37,'• Inhaled salmeterol: maximum 200 micrograms over 24 hours;'),(4,38,'Inhaled vilanterol: maximum 25 micrograms over 24 hours'),(8,153,'Aerosol: 20–40 micrograms, 3–4 times daily. Nebuliser: 250–500 micrograms, 3–4 times daily.'),(9,154,'Tablet: 5 mg chewable or 10 mg. Adult: 10 mg once daily in the evening.'),(10,155,'Inhalation: 18 micrograms once daily (capsule) or 5 micrograms (2 puffs) once daily (solution).'),(11,152,'Inhalation aerosol: 100 or 200 micrograms per dose. Adult: 200–400 micrograms once daily; maximum 800 micrograms per dose.'),(13,167,'Inhalation: 80/4.5 or 160/4.5 micrograms per inhalation. Maximum 4 inhalations every 12 hours.'),(14,159,'Injection: 1 mg (as hydrochloride or hydrogen tartrate) in 1 mL ampoule.'),(15,156,'Capsule: 150 mg. Adult: 150 mg every 12 hours.'),(16,157,'Tablets: 267 mg. Adult: 267 mg three times daily for 7 days, then 534 mg three times daily for 7 days, then 801 mg three times daily. Take with food.'),(17,158,'Inhalation aerosol: 100 micrograms + 50 micrograms. Adult and paediatric: 2 inhalations, 3 or 4 times daily.'),(18,231,'Inhalation, 250-mL bottle. Adult induction: gradually increase inspired gas concentration to 2–4%. Maintenance: 0.5–2%.'),(19,232,'Inhalation, 250 mL. Adult induction: initially 0.5%, increased to 3%. Maintenance: 1–2.5%.'),(20,233,'Inhalation vapour liquid, 250 mL. Adult induction: initially 0.5–1%, increased up to 8%. Maintenance: 0.5–3%.'),(21,234,'Injection, 100 micrograms/mL (2 mL). Adult IV infusion: 0.7 microgram/kg/hour; usual dose 0.2–1.4 micrograms/kg/hour.'),(22,235,'Injection, 2 mg/mL (10 mL vial). Adult IV induction: 0.3 mg/kg; range 0.2–0.6 mg/kg.'),(23,236,'Injection, 50 mg (as HCl)/mL in 10-mL vial. Adult induction: IM 4–6 mg/kg; IV 1–2 mg/kg.'),(24,237,'Injection, 1 mg as HCl/mL in 5-mL amp. Adult conscious sedation: initially 2–2.5 mg; usual total dose 3.5–5 mg; maximum 7.5 mg per course.'),(25,238,'Injection, 10 mg/mL in 20-mL vial. Adult induction: 1.5–2.5 mg/kg for ages 18–54 years.'),(26,239,'Powder for injection, 2 mg/2 mL. Adult initial IV bolus: 0.25–1 microgram/kg over at least 30 seconds.'),(27,240,'Powder for injection, 500 mg vial. Adult induction: usually 100–150 mg, may repeat 100–150 mg, or up to 4 mg/kg; maximum 500 mg.'),(33,246,'Injection 0.5% HCl, 10-mL vial; spinal injection 0.5% HCl with glucose 8%. Adult regional sympathetic block: 75–150 mg. Other block doses depend on the procedure.'),(34,247,'Injection 2% HCl in 30-mL vial; topical spray 2%, 4%, 10%. Adult local infiltration: maximum 200 mg, or maximum 500 mg when given in solutions containing adrenaline.'),(35,248,'Injection 20 mg. Adult malignant hyperthermia: initially 2–3 mg/kg by rapid IV injection, then 1 mg/kg repeated if necessary; maximum 10 mg/kg per course.'),(36,249,'Injection 30 mg as HCl per 1 mL. Adult reversal of hypotension from spinal or epidural anaesthesia: 3–6 mg every 3–4 minutes; maximum 9 mg per dose and 30 mg per course.'),(37,250,'Injection 50 micrograms/mL as citrate in 2-mL ampoule. Adults and children 12 years and above: minor surgery 0.5–2 micrograms/kg/dose IV.'),(38,251,'Injection 10 mg as HCl or sulphate per 1-mL ampoule; preservative-free injection also listed. Adult acute pain: 0.1 mg/kg every 4 hours if necessary by SC or IM injection. Severe acute pain IV: titrate 1 mg every 10 minutes until analgesia is achieved.'),(39,252,'Injection 2 mg/mL as HCl in 2-mL ampoule. Adult postoperative nausea and vomiting: 4 mg IV as a single dose before anaesthesia or at the end of surgery.'),(40,253,'Injection 10 mg/mL hydrochloride in 1-mL ampoule. Used as an adjunct for intractable hypotension after epidural or spinal anaesthesia.'),(48,268,'Powder for injection 10 mg as bromide vial. Adult IV intubation: initially 80–100 micrograms/kg; usual maintenance 20–30 micrograms/kg. IV infusion: initially 40–100 micrograms/kg, then 0.8–1.4 micrograms/kg/min.'),(49,269,'Injection 2.5 mg/mL. Adult reversal of non-depolarizing block: 2.5 mg IV over 1 minute, followed if necessary by 500 microgram supplements to a maximum total dose of 5 mg.'),(50,270,'Injection 5 mg/mL and tablet 60 mg as bromide. Adult myasthenia gravis: initially 30–120 mg orally at suitable intervals; usual total daily dose 0.3–1.2 g.'),(51,261,'Inhalation (medical gas). KNMF does not specify a fixed dosage; used as a medical gas/carrier gas.'),(52,262,'Inhalation (medical gas). Anaesthesia: nitrous oxide mixed with 25–30% oxygen. Analgesia: 50% nitrous oxide mixed with 50% oxygen. Paediatric anaesthesia: up to 66% in oxygen; analgesia up to 50% in oxygen.'),(53,263,'Inhalation (medicinal gas). Concentration depends on the condition being treated. Concentration of oxygen in inspired anaesthetic gases should never be below 29–30%.'),(54,264,'Injection 10 mg/mL. Adult IV: initially 300–600 micrograms/kg, then 100–200 micrograms/kg as required; alternatively infusion 300–600 micrograms/kg/hour.'),(55,265,'Injection 2 mg/mL. Adult IV: initially 150 micrograms/kg, then 30 micrograms/kg every 20 minutes; alternatively infusion initially 180 micrograms/kg/hour, then maintenance 60–120 micrograms/kg/hour.'),(56,266,'Injection 10 mg/mL as bromide, 5-mL vial. KNMF presentation confirmed; specific dose not entered here because the verified source extract did not expose the dosing section.'),(57,267,'Injection 50 mg/mL as chloride, 2-mL ampoule. Also known as succinylcholine. KNMF presentation confirmed; specific dose not entered here because the verified source extract did not expose the dosing section.'),(58,271,'Injection, 1 mg as sulphate/mL. Adult organophosphate or carbamate poisoning: initially 1–2 mg for mild poisoning and up to 6 mg for severe poisoning every 5–10 minutes until adequate response.'),(59,272,'Injection, 200 micrograms as bromide/mL. Adult premedication: 200–400 micrograms IM or IV, alternatively 4–5 micrograms/kg; maximum 400 micrograms per dose. Intra-operative bradycardia: 200–400 micrograms IV, repeated if necessary.'),(60,276,'Tablet, 300 mg. Adult mild to moderate pain and pyrexia: 300–900 mg orally every 4–6 hours if necessary; maximum 4 g daily. In inflammatory arthritis: 4–8 g daily in divided doses for acute conditions.'),(61,277,'Capsule, 200 mg. Osteoarthritis: 200 mg daily in 1–2 divided doses, increasing if necessary to 200 mg twice daily. Rheumatoid arthritis: 100 mg twice daily, increasing if necessary to 200 mg twice daily.'),(62,278,'Tablet, 25 mg; injection, 25 mg/mL. Adult oral treatment: 25 mg every 8 hours, maximum 75 mg/day. IV or IM: 50 mg every 8–12 hours; maximum 150 mg/day. Treatment should be limited to the acute symptomatic period.'),(63,279,'Tablet, 200 mg; oral liquid, 100 mg/5 mL. Adult mild to moderate pain, pyrexia and inflammatory musculoskeletal disorders: 1.2–1.8 g daily in 3–4 divided doses; maximum 2.4 g daily, or 3.2 g daily in inflammatory disease.'),(64,280,'Injection, 30 mg/mL. Adult postoperative pain: initially 10 mg, then 10–30 mg every 4–6 hours as required for a maximum of 2 days. Maximum 60 mg/day for body weight up to 50 kg and 90 mg/day for body weight 50 kg and above.'),(65,281,'Oral liquid, 120 mg/5 mL; tablet, 500 mg. Acute migraine: 0.5–1 g orally at first sign of attack, repeated every 4–6 hours if necessary; maximum 4 g daily.'),(66,282,'Tablet, 30 mg as phosphate. Adult mild to moderate pain: 30–60 mg orally every 4 hours when necessary; maximum 240 mg daily. Chronic severe pain using modified-release medicines: 60–120 mg every 12 hours.'),(67,283,'Concentrate for oral liquid, 5 mg/mL as HCl. Adult opioid dependence: initially 10–40 mg daily, increased by up to 10 mg daily as required; usual maintenance dose 60–120 mg daily.'),(68,285,'Tablet, 25 mg. Adult depression: initially 75 mg daily, increased gradually to 150–200 mg daily if necessary. Neuropathic pain: initially 10–25 mg daily in the evening; usual dose 25–75 mg daily.'),(69,286,'Tablet, 5 mg. Adult constipation: 5–10 mg once daily, increased if necessary up to 20 mg once daily, taken at night. Bowel clearance before procedures: initially 10 mg twice daily on the day before the procedure.'),(70,287,'Oral liquid, 100 mg/5 mL; tablet, 200 mg. Adult seizures: initially 100–200 mg 1–2 times daily, increased gradually according to response; usual maintenance 0.8–1.2 g daily in divided doses.'),(71,291,'Injection, 4 mg as sodium phosphate/mL; tablets 500 micrograms and 4 mg. Adult allergy: 0.5–10 mg daily. Anaphylaxis adjunct: 0.5–24 mg by slow IV injection or infusion.'),(72,292,'Rectal gel, 5 mg/mL. Adult: 500 micrograms/kg rectally, then 500 micrograms/kg after 12 hours if required. Elderly: 250 micrograms/kg, then 250 micrograms/kg after 12 hours if required.'),(73,293,'Tablet, 300 mg. Adult focal seizures: initially 300 mg once daily on day 1, 300 mg twice daily on day 2, then 300 mg three times daily on day 3; usual dose 0.9–3.6 g daily in 3 divided doses.'),(74,294,'Injection, 5 mg/mL; tablet, 5 mg. Adult oral treatment: 2.5–5 mg 2–3 times daily. In severely affected or resistant patients, 3–5 mg 2–3 times daily; resistant schizophrenia may require up to 30 mg daily.'),(75,295,'Tablet, 10 mg; injection, 20 mg/mL. Adult smooth muscle spasm: 20 mg orally four times daily. Acute spasm by IM or IV injection: 20 mg, repeated after 30 minutes if necessary; maximum 100 mg daily.'),(76,296,'Oral liquid, 3.1–3.7 g/5 mL. Adult constipation: initially 15 mL twice daily, adjusted according to response. Hepatic encephalopathy: 30–50 mL three times daily, adjusted to produce 2–3 soft stools per day.'),(77,297,'Capsule, 2 mg. Adult acute diarrhoea: initially 4 mg, followed by 2 mg for up to 5 days; usual dose 6–8 mg daily, maximum 16 mg daily. Chronic diarrhoea: initially 4–8 mg daily in divided doses, adjusted according to response.'),(78,298,'Injection, 5 mg/mL (2-mL amp); tablet, 10 mg. Adult: 10 mg three times daily. Premedication by slow IV injection: 10 mg.'),(79,299,'Oral liquid, 15 mg/5 mL; tablet, 5 mg. Adult: initially 10–20 mg daily; in severe disease up to 60 mg daily. Maintenance: 2.5–15 mg daily or higher.'),(80,300,'Capsule, 25 mg or 75 mg. Adult diabetic peripheral neuropathic pain: initially 50 mg every 8 hours; may increase to 100 mg every 8 hours within 1 week; maximum 300 mg in 24 hours.'),(81,301,'Tablet, 7.5 mg. Adult opioid-induced constipation: 7.5–15 mg once daily at bedtime; maximum 30 mg daily.'),(82,302,'Tablet, 10 mg; oral liquid, 1 mg/mL. Adult: 10 mg once daily.'),(83,306,'Injection, 10 mg as maleate/mL; oral liquid, 2 mg as maleate/5 mL. Adult allergic reactions/anaphylaxis adjunct: 10–20 mg by SC, IM or IV injection; maximum 40 mg in 24 hours.'),(84,307,'Injection, 50 mg/mL. Adult: 10–50 mg by IV or deep IM injection every 4–6 hours; maximum 400 mg daily.'),(85,308,'Powder for injection, 100 mg as sodium succinate vial. Adult acute hypersensitivity reactions/anaphylaxis adjunct: 100–300 mg by IV injection.'),(86,309,'Tablet, 10 mg. Adult symptomatic relief of allergy such as hay fever and urticaria: 10 mg daily.'),(87,310,'Powder for oral liquid, 50 g. Adult poisoning: 50–100 g orally as a single dose, as soon as possible after ingestion of poison. Paediatric: 1 g/kg orally, maximum 50 g as a single dose; for active elimination, 1 g/kg every 4 hours, maximum 50 g.'),(88,311,'Injection, 200 mg/mL in 10-mL amp. Adult paracetamol overdose: IV initially 150 mg/kg over 1 hour, then 50 mg/kg over 4 hours, then 100 mg/kg over 16 hours. Oral use of injectable formulation: loading dose 140 mg/kg, then 70 mg/kg every 4 hours for 17 doses.'),(89,312,'Injection, 10 mg/mL (5-mL vial). Adult methotrexate toxicity: up to 120 mg in divided doses over 12–24 hours, then 12–15 mg IM or 15 mg orally every 6 hours for 48–72 hours.'),(90,313,'Injection, 100 mg/mL in 10-mL amp. Adult: for severe hyperkalaemia, acute hypocalcaemia or magnesium toxicity, 1 g by slow IV injection; for cardiotoxicity, 1.5–3 g over 2–5 minutes.'),(91,314,'Tablet, 100 mg or 400 mg. Adult transfusion-related chronic iron overload: initially 7–21 mg/kg once daily; adjust according to serum ferritin and transfusion requirements. Adjust in steps of 3.5–7 mg/kg every 3–6 months; maximum 28 mg/kg/day, usual maximum 21 mg/kg/day.'),(92,315,'Powder for injection, 500 mg as mesilate per vial. Adult acute iron poisoning: IV infusion initially 15 mg/kg/hour, reduced after 4–6 hours; total dose should not exceed 80 mg/kg in 24 hours. Chronic iron overload: usually 20–60 mg/kg/day by SC or IV infusion, 4–7 days per week.'),(93,563,'Powder for injection, 500 mg as mesilate per vial. Adult acute iron poisoning: IV infusion initially 15 mg/kg/hour, reduced after 4–6 hours; total dose should not exceed 80 mg/kg in 24 hours. Chronic iron overload: usually 20–60 mg/kg/day by SC or IV infusion, 4–7 days per week.'),(95,316,'Injection, 100%; oral medicinal liquid, 95–96%. Adult methanol or ethylene glycol poisoning: IV initial 600–700 mg/kg (7.6–8.9 mL/kg) using a 10% solution, or oral initial 600–700 mg/kg using a 98% solution. Maintain serum ethanol above 100 mg/dL.'),(96,321,'Injection, 5 mg/mL as sulphate in 20-mL amp. Adult ethylene glycol or methanol poisoning: loading dose 15 mg/kg, followed by 10 mg/kg every 12 hours for 4 doses, then 15 mg/kg every 12 hours until serum toxic alcohol concentration is below 20 mg/100 mL. IV infusion over 30 minutes.'),(97,322,'Injection, 100 micrograms/mL in 5-mL amp. Adult benzodiazepine sedation reversal: 200 micrograms IV over 15 seconds, then 100 micrograms every minute if required; usual dose 300–600 micrograms, maximum 1 mg per course. Intensive care: 300 micrograms initially, then 100 micrograms every minute if required; maximum 2 mg per course.'),(98,323,'Injection, 20% in 200–500 mL. Adult local anaesthetic systemic toxicity: 1.5 mL/kg of 20% lipid emulsion as a rapid bolus, followed by 0.25 mL/kg/min infusion. The same bolus may be repeated if cardiovascular instability continues; recommended dosing limit approximately 12 mL/kg.'),(99,324,'Injection, 400 micrograms/mL as HCl. Adult opioid overdose: 0.4–2 mg IV, repeated every 2–3 minutes up to a maximum of 10 mg. If IV administration is not feasible, IM or SC administration may be used. Continuous IV infusion: 10 mg diluted in 50 mL glucose 5%, adjusted according to response.'),(100,325,'Injection, 10 mg/mL in 1-mL amp. Adult: warfarin antagonism, 500 micrograms by slow IV injection or up to 5 mg orally; moderate haemorrhage, 10–20 mg orally or IM; severe haemorrhage, 5–10 mg by slow IV injection.'),(101,326,'Powder for injection, 1 g as chloride or mesylate per vial. Adult organophosphorus poisoning: initially 30 mg/kg IV over 20 minutes, followed by 8 mg/kg/hour; maximum 12 g/day.'),(102,327,'Injection, 10 mg/mL as sulphate. Adult heparin overdose: 1 mg neutralizes approximately 80–100 IU heparin sodium when given within 15 minutes; less is required when more time has elapsed.'),(103,328,'Injectable solution, 8.4% in 10-mL amp. Adult metabolic acidosis: slow IV injection of strong solution up to 8.4% or continuous IV infusion of a weaker solution, usually 1.4%, with amount determined by acid-base status.'),(104,329,'Injection, 30 mg/mL in 10-mL amp. Adult cyanide poisoning: 300 mg IV (10 mL of a 3% solution) over 2–20 minutes, followed by sodium thiosulphate.'),(105,330,'Injection, 250 mg/mL in 50-mL amp. Adult cyanide poisoning: 12.5 g IV (50 mL of a 25% solution or 25 mL of a 50% solution) over 10 minutes after sodium nitrite.'),(106,331,'Capsule, 100 mg. Adult lead and mercury poisoning: 10 mg/kg or 350 mg/m2 orally every 8 hours for 5 days, then every 12 hours for an additional 14 days.'),(107,332,'Tablet, 250 mg or 500 mg. Adult adjunct in epilepsy: 8–30 mg/kg/day orally, with daily dose divided every 12 hours; maximum 1 g/day.'),(108,336,'Tablet, 10 mg. Adult adjunct treatment of seizures: 20–30 mg/day in divided doses or once daily at bedtime; may be increased to a maximum of 60 mg/day in divided doses.'),(109,337,'Tablet, 0.5 mg or 2 mg. Adult adjunct treatment of epilepsy: initially 1 mg once daily for four nights, then increase every 3 days over 2–4 weeks; maintenance dose 2–8 mg daily.'),(110,338,'Tablet, 5 mg chewable/dispersible or 25 mg, 100 mg tablet. Adult dosing depends on concurrent medicines; titrate gradually according to the KNMF regimen.'),(111,339,'Injection IV 500 mg; tablet 500 mg; oral solution 100 mg/mL. Adult epilepsy: initially 500 mg twice daily, increasing according to response; usual maintenance 500–1500 mg twice daily.'),(112,340,'Injection 4 mg/1 mL. Adult convulsive status epilepticus: 4 mg by slow IV injection; may be repeated after 10 minutes if required.'),(113,341,'Injection 500 mg/mL (50%) in 10-mL ampoule/vial. Adult eclampsia: initially 4 g IV over 5–15 minutes, followed by 1 g/hour IV infusion, or 5 g IM into each buttock followed by 5 g every 4 hours.'),(114,342,'Tablet, 150 mg or 300 mg. Adult adjunct treatment of epilepsy: initially 300 mg every 12 hours; may increase by 600 mg/day at weekly intervals up to 1200 mg/day.'),(115,343,'Injection 30 mg/1 mL or 200 mg/1 mL; tablet 30 mg. Adult generalized or partial seizures: 180 mg at night. Status epilepticus: 10 mg/kg by IV injection, maximum 1 g.'),(116,344,'Injection 50 mg/mL; oral liquid 30 mg/5 mL; tablet/capsule 50 mg or 100 mg. Adult generalized or partial seizures: initially 3–4 mg/kg/day, usual maintenance 200–500 mg/day. Status epilepticus: 15 mg/kg loading dose, then 100 mg every 6–8 hours.'),(117,345,'Tablet 25 mg or 50 mg. Adult monotherapy: initially 25 mg every 12 hours, increasing by 50 mg/day weekly up to 200 mg every 12 hours. Adjunct treatment: initially 25–50 mg/day, increasing by 25–50 mg/day weekly according to response.'),(118,346,'Injection 100 mg/mL; oral liquid 200 mg/5 mL; tablets 200 mg or 500 mg and 100 mg crushable. Adult epilepsy: initially 600 mg/day in 2 divided doses, increasing by 200 mg/day every 3 days to a maximum of 2.5 g/day; usual maintenance 1–2 g/day.'),(119,347,'Tablet, chewable 400 mg; oral suspension 100 mg/5 mL. Adult: ascariasis, hookworm, enterobiasis and trichostrongyloidiasis 400 mg as a single dose; whipworm 400 mg as a single dose or daily for 3 days; strongyloidiasis 400 mg once or twice daily for 3–7 days.'),(120,351,'Tablet, 500 mg (chewable/dispersible). Adult enterobiasis: 100 mg as a single dose, repeated after 2–3 weeks. Capillariasis: 200 mg daily for 20–30 days. Mass treatment: 500 mg as a single dose 4 times a year.'),(121,352,'Tablet, 600 mg. Adult clonorchiasis/opisthorchiasis: 25 mg/kg per dose 3 times daily for 1–2 days. Taenia saginata/T. solium: 5–10 mg/kg as a single dose. Hymenolepis nana: 15–25 mg/kg as a single dose. Cysticercosis: 50 mg/kg daily in 3 divided doses for 15 days.'),(122,353,'Tablet, 100 mg as dihydrogen citrate. Adult filariasis: dose according to body weight and indication; take immediately after meals.'),(123,354,'Tablet, 3 mg. Adult onchocerciasis/lymphatic filariasis: 200 micrograms/kg as a single dose; suppression of microfilariae: 150 micrograms/kg once yearly; strongyloidiasis: 200 micrograms/kg daily for 1–2 days.'),(124,355,'Injection, 50 mg/mL or 250 mg/mL as sulphate in 2-mL vial. Adult serious Gram-negative infections: 15 mg/kg/day in 2 divided doses, increased to 22.5 mg/kg/day in 3 divided doses for up to 10 days; maximum 1.5 g/day and 15 g per course. Once-daily regimen: initially 15 mg/kg once daily, maximum 1.5 g per dose.'),(125,168,'Tablet 250 mg; capsule 500 mg; oral liquid 125 mg/5 mL or 250 mg/5 mL. Adult infections: 500 mg every 8 hours or 750–1000 mg every 12 hours; for severe infections 750–1000 mg every 8 hours for 10 days.'),(126,356,'Powder for injection, 500 mg. Adult: listeria infections, intrapartum prophylaxis, high-risk GI endoscopy and listerial meningitis: IV infusion 12 g daily in divided doses every 4–6 hours for 10–14 days. Intrapartum prophylaxis: 2 g IV intrapartum.'),(127,357,'Powder for injection, 900 mg (1.2 million units) vial. Adult primary/secondary syphilis: 2.4 million units by deep IM injection as a single dose. Late-stage syphilis: 2.4 million units once weekly for 3 weeks.'),(128,358,'Powder for injection, 600 mg (1 million units) or 3 g (5 million units) as sodium or potassium salt. Adult mild to moderate infections: 2.4–4.8 g daily in 4 divided doses; severe infections require higher doses. Bacterial endocarditis: 7.2–14.4 g daily in 6 divided doses.'),(129,359,'Oral liquid 125 mg/5 mL; capsule 250 mg. Adult skin and soft tissue infections, streptococcal pharyngitis and mild uncomplicated UTI: 250 mg every 6 hours or 500 mg every 12 hours. Hospital-acquired pneumonia: 500 mg 2–3 times daily, up to 1.5 g 3–4 times daily.'),(130,360,'Powder for injection, 500 mg or 1 g as sodium salt. Adult surgical prophylaxis: 1 g at induction, followed by 0.5–1 g during lengthy procedures and 0.5–1 g every 6–8 hours after surgery for 24 hours. Infections: 250 mg–2 g every 6–12 hours depending on severity; maximum 12 g/day.'),(131,361,'Capsule, 100 mg as hydrochloride. Adult susceptible bacterial infections: acne 40–50 mg daily for 6–12 weeks; uncomplicated genital chlamydia/non-gonococcal urethritis 100 mg every 12 hours for 7 days; refractory UTI/STIs 200 mg daily; cellulitis/erysipelas initially 200 mg daily then 100 mg once daily for 5–7 days.'),(132,366,'Capsule 250 mg or 500 mg; oral liquid 125 mg/5 mL; injection 500 mg vial. Adult infections: oral 250–500 mg 4 times daily; IM 250–500 mg every 6 hours; slow IV injection/infusion 0.25–1 g every 6 hours. Severe infections may require higher doses.'),(133,367,'Injection, 10 mg/mL or 40 mg/mL as sulphate. Adult susceptible infections: 3–5 mg/kg daily in divided doses every 8 hours for severe infections for 7–10 days. Endocarditis: 1 mg/kg every 8 hours. Surgical prophylaxis: 5 mg/kg as a single dose at induction.'),(134,196,'Injection, 500 mg/100 mL; oral liquid 40 mg/mL; tablet 400 mg. Adult anaerobic bacterial infections: oral 800 mg initially, then 400 mg every 8 hours. IV: 500 mg every 8 hours by infusion, usually for about 7 days; maximum 4 g daily. Bacterial vaginosis: 2 g single dose or 400–500 mg twice daily for 5–7 days.'),(135,368,'Tablet, 100 mg; oral liquid, 25 mg/5 mL. Adult uncomplicated UTI: 100 mg every 12 hours or 50 mg every 6 hours with food for 7 days. Severe recurrent UTI: 100 mg every 6 hours for 7 days. Prophylaxis: 50–100 mg at night.'),(136,369,'Powder for oral liquid, 250 mg/5 mL as potassium salt; tablet 250 mg. Adult infections: 125–250 mg every 6–8 hours for 10 days, or 500 mg every 6 hours for lower respiratory tract infections. Severe infections: up to 1 g every 6 hours. Rheumatic fever prophylaxis: 250 mg twice daily.'),(137,370,'Tablet, 500 mg. Adult anaerobic infections: initially 2 g, followed by 1 g daily for 5–6 days, alternatively 500 mg twice daily. Bacterial vaginosis: 2 g as a single dose or other regimens specified by KNMF. Abdominal surgery prophylaxis: 2 g as a single dose approximately 12 hours before surgery.'),(138,371,'Tablet, 500 mg; oral liquid, 200 mg/5 mL. Adult respiratory tract, otitis media, skin and soft tissue infections: 500 mg once daily for 3 days, alternatively 500 mg once daily for 1 day then 250 mg once daily for 4 days. Chlamydial infection: 1 g as a single dose.'),(139,372,'Tablet 400 mg. Adult: uncomplicated anogenital gonorrhoea, 400 mg as a single oral dose; susceptible infections, 200–400 mg daily as a single dose or in 2 divided doses for 7 days, extendable to 14 days if necessary.'),(140,373,'Powder for injection 500 mg or 1 g. Paediatric severe susceptible infections/meningitis: neonate up to 7 days, 50 mg/kg every 12 hours; 7–20 days, 50 mg/kg every 8 hours; 21–28 days, 50 mg/kg every 6–8 hours; child, 50 mg/kg every 6 hours, maximum 12 g/day.'),(141,374,'Powder for injection 250 mg or 1 g. Adult: cystic-fibrosis bronchopulmonary infection, 100–150 mg/kg/day (maximum 9 g/day); febrile neutropenia, nosocomial pneumonia, bacteraemia and meningitis, 2 g every 8 hours; bone, joint, skin and soft-tissue and intra-abdominal infections, 2 g every 8 hours.'),(142,375,'Injection IM/IV 250 mg or 1 g. Adult: community/hospital-acquired pneumonia, intra-abdominal and complicated urinary-tract infections, 1–2 g once daily; severe cases may require up to 4 g/day. Gonorrhoea: 250–500 mg as a single dose. Surgical prophylaxis: 1–2 g at induction.'),(143,376,'Powder for injection 750 mg. Adult surgical prophylaxis: 1.5 g up to 30 minutes before the procedure, then 750 mg every 8 hours if required for up to 3 doses in high-risk procedures.'),(144,381,'Injection 400 mg; tablet 500 mg as hydrochloride. Adult susceptible infections: oral 500–750 mg twice daily; IV infusion 400 mg every 8–12 hours. Acute uncomplicated cystitis: 250–500 mg twice daily for 3 days. Gonorrhoea: 500 mg as a single dose.'),(145,382,'Tablet 500 mg. Adult respiratory-tract and mild to moderate skin/soft-tissue infections: 250 mg twice daily for 7–14 days, increased to 500 mg twice daily for severe infections; community-acquired pneumonia: 500 mg twice daily for 5 days; H. pylori eradication: 500 mg twice daily for 7–10 days in combination therapy.'),(146,383,'Capsule 150 mg; injection 150 mg/mL; oral liquid 15 mg/mL. Adult severe infections: 150–300 mg orally every 6 hours, up to 450 mg every 6 hours. Life-threatening infections: 0.6–2.7 g daily in 2–4 divided doses, increased up to 4.8 g daily when required.'),(147,170,'Injection 80 mg + 16 mg/mL; oral liquid 40 mg + 8 mg/mL; tablet 800 mg + 160 mg. Adult Pneumocystis jirovecii pneumonia: sulfamethoxazole up to 100 mg/kg/day plus trimethoprim up to 20 mg/kg/day in 2–4 divided doses for 14–21 days. Prophylaxis: 800 mg + 160 mg or 400 mg + 80 mg.'),(148,385,'Tablet 250 mg or 500 mg. Adult susceptible respiratory, skin and oral infections: 250–500 mg four times daily; severe infections up to 1 g four times daily. Community-acquired pneumonia: 500 mg four times daily for 5 days. Early syphilis: 500 mg four times daily for 14 days.'),(149,172,'Powder for injection, 4 g + 500 mg as sodium salt. Adult hospital-acquired pneumonia, sepsis and complicated urinary, skin and soft-tissue infections: 4.5 g IV every 8 hours. Neutropenia or severe pneumonia: 4.5 g IV every 6 hours.'),(150,389,'Granules for oral suspension 3 g sachet; powder for injection 3 g as sodium. Adult uncomplicated lower urinary-tract infection: 3 g orally as a single dose. IV treatment of serious infections: 12–24 g daily in 2–3 divided doses; maximum 8 g per dose.'),(151,390,'IV injection 2 mg/mL in 300 mL; tablet 600 mg. Adult: 600 mg every 12 hours, usually for 10–14 days; maximum treatment duration 28 days.'),(152,391,'Powder for injection 500 mg as trihydrate. Adult: serious infections by IV injection/infusion 0.5–1 g every 8 hours; meningitis and endocarditis 2 g every 8 hours.'),(153,392,'Powder for injection 500,000 units vial. Adult acute susceptible Pseudomonas infections: IV infusion up to 15,000 units/kg/day, divided into doses; total daily dose should not exceed 25,000 units/kg/day.'),(154,396,'Injection 200 mg. Adult serious Gram-positive infections: initially 6 mg/kg every 12 hours for 3 doses, then 6 mg/kg once daily. Endocarditis and bone/joint infections: 12 mg/kg every 12 hours for 3–5 doses, then 12 mg/kg once daily.'),(155,397,'Powder for injection 50 mg vial. Adult complicated skin/soft-tissue and intra-abdominal infections: initially 100 mg IV, followed by 50 mg every 12 hours for 5–14 days.'),(156,398,'Powder for injection 500 mg as hydrochloride. Adult serious staphylococcal infections: 500 mg IV over at least 60 minutes every 6 hours, or 1 g over at least 100 minutes every 12 hours. Antibiotic-associated colitis: 125–500 mg orally every 6 hours for 7–10 days.'),(157,399,'Capsule 50 mg or 100 mg. Adult multibacillary leprosy: 50 mg orally once daily and 300 mg once a month. Type 2 lepra reaction: 100–200 mg daily in 2–3 divided doses for a maximum of 3 months.'),(158,400,'Tablet 100 mg or 25 mg. Adult paucibacillary leprosy: 100 mg orally daily for at least 6 months. Multibacillary leprosy: 100 mg orally daily for 12 months, as part of combination therapy.'),(159,174,'Tablet/capsule 150 mg or 300 mg. Adult leprosy treatment: 600 mg orally once monthly, alternatively 10 mg/kg once monthly; maximum 450 mg for patients under 50 kg and 600 mg for patients 50 kg or above.'),(160,177,'Tablet (dispersible) 100 mg; tablet 400 mg. Adult TB treatment in combination with other medicines: 15 mg/kg daily or 30 mg/kg three times weekly; for retreatment, 25 mg/kg once daily for 60 days, then 15 mg/kg once daily. Recommended maximum 1.6 g daily.'),(161,175,'Tablet 100 mg or 300 mg; scored tablet 50 mg; injection 100 mg/mL. Adult TB treatment: 5 mg/kg (4–6 mg/kg) daily, maximum 300 mg daily, or 10 mg/kg, maximum 900 mg/day, three times weekly. TB prophylaxis: 300 mg daily for at least 6 months.'),(162,176,'Tablet 500 mg; dispersible/scored tablet 150 mg. Adult TB treatment in combination with other medicines: for standard unsupervised 2-month treatment, under 50 kg: 1.5 g daily; 50 kg or above: 2 g daily. For intermittent supervised treatment, under 50 kg: 2 g three times weekly; 50 kg or above: 2.5 g three times weekly.'),(163,612,'Tablet 100 mg. Adult multiple-drug-resistant pulmonary TB: 400 mg once daily for 2 weeks, then 200 mg three times weekly for 22 weeks (Monday, Wednesday and Friday), taken with food.'),(164,613,'Tablet 250 mg and 125 mg. Adult MDR-TB treatment in combination with other medicines: 15–20 mg/kg daily for 18 months. The KNMF gives 500 mg for 33–50 kg, 750 mg for 51–70 kg, and 750–100 mg for over 70 kg.'),(165,614,'Tablet 50 mg. Adult multiple-drug-resistant pulmonary TB resistant to fluoroquinolones: 100 mg twice daily for 24 weeks with appropriate combination therapy, followed by 14 months with appropriate combination therapy.'),(166,179,'Injection 500 mg + 500 mg vial. Adult: 2.5 g IV every 8 hours for severe infections; dose adjusted according to infection and renal function.'),(167,180,'Injection 500 mg + 500 mg vial. Used in combination with imipenem; adult dose is determined as part of the imipenem/cilastatin regimen.'),(185,185,'Tablet 300 mg. Adult HIV treatment: 300 mg once daily in combination with other antiretroviral medicines.'),(186,615,'Tablet (dispersible) 100 mg, tablet 250 mg, 500 mg and 750 mg. Adult MDR-TB: 750 mg daily; if body weight is over 70 kg, 750–1000 mg daily.'),(187,616,'Tablet (dispersible) 100 mg; tablet 400 mg. Adult drug-resistant TB: 400 mg daily across all weight classes.'),(188,617,'Granules, 4 g in sachet. Adult MDR-TB: 33–50 kg: 8 g daily; 51–70 kg: 8 g daily; over 70 kg: 8–12 g daily.'),(189,403,'Tablet, 250 mg. Adult drug-resistant TB: 15–20 mg/kg daily, maximum 1 g daily; may be given in divided doses with meals or as a single daily dose.'),(190,404,'Tablet, 300 mg. Adult MDR-TB: initially 250–500 mg per day in one or two divided doses, increased to 1000 mg per day; usual target 15–20 mg/kg/day, maximum 1 g per day. Weight-based doses: 33–50 kg: 500 mg; 51–70 kg: 750 mg; over 70 kg: 750–1000 mg.'),(191,405,'Tablet, 200 mg. Adult pulmonary XDR/MDR-TB in combination therapy: 200 mg once daily for 26 weeks; to be taken with food.'),(192,407,'Vaginal tablet, 500 mg. Adult vaginal candidiasis: 500 mg at night as a single dose.'),(193,408,'Capsule/tablet 150 mg and 200 mg; injection 2 mg/mL; oral liquid 50 mg/5 mL. Adult systemic mycoses: initial 800 mg, then 400 mg daily; cryptococcal meningitis: 800 mg daily for 2 weeks, then 400 mg daily for 8 weeks; vaginal candidiasis: 150 mg single dose.'),(194,409,'Injection 2.5 g/250 mL; capsule 250 mg. Adult: 200 mg/kg daily in four divided doses by IV infusion for up to 7 days, or 100–150 mg/kg daily in four divided doses; oral 50–150 mg/kg daily in four divided doses.'),(195,410,'Tablet 125 mg and 500 mg. Adult superficial fungal infections: 0.5–1 g daily (not less than 10 mg/kg), in single or divided doses with fatty food.'),(196,411,'Capsule 100 mg. Adult oropharyngeal candidiasis: 100 mg daily for 15 days; vulvovaginal candidiasis: 200 mg twice daily for 1 day; systemic infections: 100–200 mg once daily, increased to 200 mg twice daily for invasive/disseminated infections.'),(197,412,'Oral liquid (suspension) 100,000 IU/mL. Adult oral candidiasis: 100,000 units after food four times daily, usually for 7 days; intestinal and esophageal candidiasis: 500,000 units four times daily.'),(198,413,'Injection 18 mg/mL (300 mg/16.7 mL); delayed-release tablet 100 mg. Adult invasive fungal infections: loading dose 300 mg twice daily on the first day, then 300 mg once daily for prophylaxis where specified.'),(199,406,'Powder for injection, 50 mg vial as deoxycholate and liposomal. Adult systemic fungal infections: deoxycholate form starts with a 1 mg test dose, then 250 micrograms/kg daily, gradually increased up to 1 mg/kg daily; in severe infection up to 1.5 mg/kg daily. Infuse over 2–6 hours.'),(200,414,'Tablet, 125 mg and 250 mg. Adult dermatophyte infections: 250 mg once daily for 2–4 weeks for tinea cruris, up to 6 weeks for tinea pedis, and 4 weeks for tinea corporis. Nail infections: 250 mg once daily for 6–12 weeks.'),(201,418,'Powder for injection, 200 mg vial; tablet 200 mg. Adult invasive fungal infections: IV initially 6 mg/kg every 12 hours for 2 doses, then 4 mg/kg every 12 hours. Oral: up to 40 kg, 200 mg every 12 hours for 2 doses then 100 mg every 12 hours; 40 kg and above, initially 400 mg every 12 hours for 2 doses.'),(202,419,'Powder for injection, 250 mg vial as sodium salt; tablet 400 mg. Adult herpes simplex: 200 mg orally 5 times daily, usually for 5 days; severe initial genital herpes or immunocompromised patients by IV infusion: 5 mg/kg every 8 hours, usually for 5 days.'),(203,186,'Oral liquid 10 mg/mL (50 mg/5 mL). Adult HIV infection: 150 mg twice daily or 300 mg once daily. Prevention of mother-to-child transmission: 150 mg at onset of labour, then 150 mg every 12 hours until delivery; after delivery 150 mg twice daily for 7 days.'),(204,187,'Tablet 25 mg. Adult HIV/AIDS: 25 mg once daily, taken with food, in combination with other antiretroviral agents.'),(205,189,'Tablet 300 mg (equivalent to 245 mg tenofovir disoproxil). Adult HIV infection: 245 mg (1 tablet) once daily.'),(206,192,'Oral liquid 10 mg/mL (50 mg/5 mL); tablet 300 mg. Adult HIV infection: 500–600 mg daily in 2–3 divided doses.'),(207,420,'Vaginal delivery system 25 mg. Adult HIV-1 pre-exposure prophylaxis: insert one ring vaginally and keep it in place until replaced each month with a new ring.'),(208,421,'Tablet 25 mg, 100 mg and 200 mg. Adult HIV infection resistant to other NNRTIs and protease inhibitors: 200 mg twice daily, taken after food, in combination with other antiretroviral drugs.'),(209,181,'Tablet 300 mg + 100 mg. Adult HIV treatment: atazanavir 300 mg once daily with ritonavir 100 mg once daily.'),(210,182,'Tablet 100 mg; oral powder 100 mg sachet. Adult HIV treatment as a booster with other antiretroviral medicines: 100 mg twice daily.'),(211,183,'Tablet 75 mg, 150 mg and 600 mg; oral liquid 10 mg/mL. Adult ART-naive patients: 800 mg once daily with ritonavir 100 mg, taken with food. ART-experienced patients: 600 mg twice daily with ritonavir 100 mg where resistance testing is not feasible.'),(212,184,'Tablet 100 mg + 25 mg or 200 mg + 50 mg; granules 40 mg + 10 mg sachet. Adult HIV treatment: lopinavir 400 mg + ritonavir 100 mg twice daily.'),(213,188,'Tablet 10 mg and 50 mg; dispersible tablet 10 mg. Adult HIV treatment: 50 mg once daily for treatment-naive or INSTI-naive patients weighing at least 30 kg; 50 mg twice daily for INSTI-experienced patients with certain resistance substitutions.'),(214,422,'Oral liquid 10 mg/mL. Adult HIV treatment: 200 mg once daily for the first 14 days, then, if no rash is present, 200 mg twice daily. Prevention of mother-to-child transmission: 200 mg as a single dose at onset of labour.'),(215,425,'Prolonged-release injection 600 mg/3 mL. Adult HIV-1 pre-exposure prophylaxis: 600 mg IM for 2 initiation doses 1 month apart, then 600 mg IM every 2 months.'),(216,426,'Injection 800 mg/10 mL; capsule 200 mg. Adult haemorrhagic fever: initially 2 g orally, then 1 g every 6 hours for 4 days, then 500 mg every 6 hours for 6 days. IV regimen: initially 17 mg/kg, then 17 mg/kg every 6 hours for 4 days, then 8 mg/kg every 8 hours for 6 days.'),(217,618,'Powder for injection 500 mg vial. Adult CMV retinitis in immunocompromised adults: induction 5 mg/kg IV every 12 hours, infused over 1 hour, for 14–21 days; maintenance may follow according to the formulary regimen.'),(218,431,'Injection 100 mg/mL. Doses are expressed as mg of pentavalent antimony. Adult leishmaniasis: 20 mg/kg daily for 20 days, or 28 days for HIV patients, by IM or IV injection.'),(219,433,'Tablet 7.5 mg and 15 mg as diphosphate. Adult P. vivax and P. ovale radical cure: 250 micrograms/kg daily (or 15 mg daily) for 14 days, or 750 micrograms/kg once weekly for 8 weeks. P. falciparum gametocytocidal treatment: 250–500 micrograms/kg as a single dose.'),(220,436,'Powder for injection 200 mg vial. Adult first-stage African trypanosomiasis: 4 mg/kg daily for 7 days or on alternate days for a total of 7–10 doses. Meningoencephalitic T. brucei gambiense stage: 4 mg/kg daily on days 1 and 2.'),(221,440,'Powder for injection 1 g vial. Adult T. brucei rhodesiense infection: 5 mg/kg on day 1, then 20 mg/kg on days 5, 11, 17, 23 and 30; maximum 1 g per injection. Alternative regimen: 20 mg/kg weekly for five weeks.'),(222,430,'Injection solution (IM), 375 mg/mL as sulphate in 2-mL amp. Adult visceral leishmaniasis: 11 mg/kg daily for 21 days by IM injection; intestinal amoebiasis: 25–35 mg/kg/day in 3 divided doses for 5–10 days.'),(223,434,'Injection 300 mg/mL as hydrochloride; tablet 300 mg as sulphate or bisulphate. Adult severe malaria: initially 20 mg/kg by slow IV infusion over 4 hours, followed by 10 mg/kg every 8 hours until oral artemether-lumefantrine can be taken. If AL is unavailable, oral quinine 10 mg/kg every 8 hours to complete 7 days.'),(224,435,'Tablet 500 mg. Adult toxoplasmosis in combination with pyrimethamine and prophylaxis of Pneumocystis jiroveci pneumonia in combination with pyrimethamine: 1 g daily.'),(232,441,'Injection 200 mg/mL as hydrochloride. Adult second-stage T. brucei gambiense infection, with nifurtimox: 100 mg/kg by IV infusion over 45 minutes every 6 hours for 14 days.'),(233,442,'Injection 36 mg/mL (3.6%) solution, 5-mL ampoule. Adult T. brucei rhodesiense or T. brucei gambiense with meningo-encephalitic involvement: 2.2 mg/kg per day by slow IV injection, maximum 5 mL, once daily for 10 days.'),(234,443,'Tablet 120 mg. Adult acute American trypanosomiasis (Chagas disease): 8–10 mg/kg daily in three divided doses for 90 days.'),(235,444,'Tablet 25 mg and 50 mg. Adult acute migraine: 25–100 mg as a single dose; a second dose may be given after at least 2 hours. Maximum 200 mg/day.'),(236,445,'Tablet 40 mg as hydrochloride. Adult migraine prophylaxis: initially 40 mg 2–3 times daily; may increase by the same amount at weekly intervals if necessary. Usual maintenance dose 80–160 mg daily.'),(237,446,'Injection 50 mg/mL (5-mL vial). Adult moderate to severe aplastic anaemia: 10–20 mg/kg once daily for 8–14 days, then every other day when needed, for a total of 21 doses in 28 days.'),(238,447,'Tablet 50 mg. Adult rheumatoid arthritis: initially 1.5–2.5 mg/kg daily in divided doses, adjusted according to response; maintenance 1–3 mg/kg daily. Crohn’s disease/ulcerative colitis maintenance: 2–2.5 mg/kg daily.'),(239,448,'Powder for injection 20 mg. Adult renal transplantation: 20 mg IV within 2 hours before transplant surgery, followed by 20 mg after 4 days; withhold second dose if severe hypersensitivity or graft loss occurs.'),(240,449,'Capsule 25 mg and 100 mg; concentrate for injection 50 mg/mL. Adult organ transplantation: 10–15 mg/kg orally 4–12 hours before surgery, then 10–15 mg/kg daily for 1–2 weeks, reducing to 2–6 mg/kg daily for maintenance. IV dose is one-third of the corresponding oral dose.'),(241,450,'Powder for injection 500 mg and 1 g. Adult severe systemic rheumatoid arthritis/connective tissue diseases: 0.5–1 g IV every 2 weeks, then reduced to 0.5–1 g monthly according to response and haematological monitoring.'),(242,451,'Tablet 500 micrograms (0.5 mg). Adult liver transplantation: initially 1 mg twice daily starting approximately 4 weeks after transplantation. Renal or heart transplantation: initially 750 micrograms twice daily, started as soon as possible after transplantation; adjust maintenance dose according to response and blood concentration.'),(243,455,'Powder for injection 125 mg and 500 mg as sodium succinate. Adult inflammatory/allergic disorders: initially 10–500 mg by slow IV injection or infusion. Graft rejection reactions: up to 1 g daily for up to 3 days. Relapse in multiple sclerosis: 1 g once daily by IV infusion.'),(244,121,'ATC code: L02BG03 Tablet, 1 mg, LOU 5 Treatment of postmenopausal women with hormone receptor-positive or hormone receptor unknown locally advanced or metastatic breast cancer, oral: 1 mg tablet taken once a day Contraindications: Pregnant or breastfeeding women. Hypersensitivity to the active substance or to any of the excipients'),(245,126,'ATC code: L02BG04 Tablets ,2.5 mg, LOU 5 » Breast cancer, adjuvant therapy: oral,2.5mg once daily for 5-10 years. » Breast cancer, advanced, first or second line therapy: oral,2.5mg once daily until disease progression. Paediatric: Safety and effectiveness not established in paediatric patients.'),(246,134,'ATC code: L02BA01 Tablet, 20 mg (as citrate), LOU 5 Adjuvan