INSERT INTO `monitoring_programs` VALUES (1,24,'presence in urine of salbutamol in excess of 1000 ng/mL is not consistent with therapeutic use of the substance and will be considered as an Adverse Analytical Finding (AAF) unless the Athlete proves, through a controlled pharmacokinetic study, that the abnormal result was the consequence of a therapeutic dose (by inhalation) up to the maximum dose indicated above.'),(2,26,'In and Out-of-Competition'),(3,27,'The presence in urine of formoterol in excess of 40 ng/mL is not consistent with therapeutic use of the substance and will be considered as an Adverse Analytical Finding (AAF) unless the Athlete proves, through a controlled pharmacokinetic study, that the abnormal result was the consequence of a therapeutic dose (by inhalation) up to the maximum dose indicated above.');
/*!40000 ALTER TABLE `monitoring_programs` ENABLE KEYS */;
